// 高校受験 理科（生物・化学）の単元に、動く図解スライドを1つずつ足す（担当 krf）。
// 「❓なぜ？→答え」の連鎖で、上に図、下の帯にそのスライドのひとこと。
import type { DiagramElement, DiagramFigure } from './figures';
import { show, bx, lb, ar, ln, ci, pg, band, fresh, flow, C, FILL } from './diagram-kit';

type E = DiagramElement[];
type Sl = { note: string; add: E };
const cap = (t1: string, t2?: string, c: string = C.ink): E =>
  band(150, lb(160, 172, t1, 12, c, 'middle', true), ...(t2 ? [lb(160, 196, t2, 11, C.gray, 'middle')] : []));
/** まっさらにして描きなおすスライド */
const N = (note: string, top: E, t1: string, t2?: string, c?: string): Sl => ({ note, add: [...fresh(...top), ...cap(t1, t2, c)] });
/** 前の図に描き足すスライド */
const A = (note: string, top: E, t1: string, t2?: string, c?: string): Sl => ({ note, add: [...top, ...cap(t1, t2, c)] });
const H = (t: string): DiagramElement => lb(160, 16, t, 12, C.ink, 'middle', true);

/** 小さなグラフ。pts は 0〜1 に正規化した点。xm は縦の点線（折れ点）の位置。 */
const mg = (ox: number, oy: number, w: number, h: number, pts: [number, number][], color: string, xm?: number): E => {
  const out: E = [ln(ox, oy, ox + w, oy, C.gray), ln(ox, oy, ox, oy - h, C.gray)];
  if (xm !== undefined) out.push(ln(ox + xm * w, oy, ox + xm * w, oy - h, C.gray, true));
  for (let i = 0; i < pts.length - 1; i++) {
    out.push(ln(ox + pts[i][0] * w, oy - pts[i][1] * h, ox + pts[i + 1][0] * w, oy - pts[i + 1][1] * h, color, false, 2.6));
  }
  return out;
};

/** 花：n 枚の花びら（円）＋まんなか */
const fl = (cx: number, cy: number, pr: number, n: number, color: string = C.red, fill: string = FILL.red, start = -90): E => {
  const out: E = [];
  for (let i = 0; i < n; i++) {
    const a = ((start + (360 / n) * i) * Math.PI) / 180;
    out.push(ci(cx + Math.cos(a) * pr * 1.15, cy + Math.sin(a) * pr * 1.15, pr, undefined, color, fill));
  }
  out.push(ci(cx, cy, pr * 0.55, undefined, C.main, FILL.yellow));
  return out;
};

const BTB = { y: '#FEF08A', g: '#BBF7D0', b: '#93C5FD' } as const;
/** 試験管（色つき液）。x は左端、液の色は BTB など */
const tube = (x: number, y: number, fill: string, label: string, sub?: string): E => [
  bx(x, y, 40, 60, '', C.gray, fill), lb(x + 20, y + 74, label, 11, C.ink, 'middle', true), ...(sub ? [lb(x + 20, y + 90, sub, 9, C.gray, 'middle')] : []),
];

