const ionG = (...which: ('H' | 'OH' | 'Na' | 'Cl')[]): E => {
  const ox = 50, oy = 128, w = 230, h = 96;
  const X = (v: number) => ox + (v / 30) * w, Y = (v: number) => oy - (v / 30) * h;
  const seg = (a: [number, number], b: [number, number], c: string) => ln(X(a[0]), Y(a[1]), X(b[0]), Y(b[1]), c, false, 2.6);
  const out: E = [ln(ox, oy, ox + w, oy, C.gray), ln(ox, oy, ox, oy - h, C.gray), ln(X(20), oy, X(20), oy - h, C.gray, true), lb(X(20), 139, '20（中和点）', 9, C.ink, 'middle'), lb(ox + w, 139, '30', 9, C.gray, 'end'), lb(ox - 4, oy + 3, '0', 9, C.gray, 'end')];
  if (which.includes('H')) out.push(seg([0, 20], [20, 0], C.red), seg([20, 0], [30, 0], C.red), lb(X(5), Y(22), 'H⁺', 11, C.red, 'middle', true));
  if (which.includes('OH')) out.push(seg([20, 0], [30, 10], C.purple), lb(X(28), Y(15), 'OH⁻', 11, C.purple, 'middle', true));
  if (which.includes('Na')) out.push(seg([0, 0], [30, 30], C.blue), lb(X(24), Y(30), 'Na⁺', 11, C.blue, 'middle', true));
  if (which.includes('Cl')) out.push(seg([0, 20], [30, 20], C.green), lb(X(8), Y(23), 'Cl⁻', 11, C.green, 'middle', true));
  return out;
};
